const STORAGE_KEY = 'chanhthu_can_tay_v4';

      // Danh mục mã – khớp với file mẫu
      const materialCatalog = [
        'RT', 'RD', 'RC', 'RK', 'R9', 'RN', 'RTA', 'RTB',
        'DT', 'DD', 'DC', 'DK', 'D9', 'DN', 'DA', 'DB',
        'MSKA', 'MSKB'
      ];

      const groupConfig = {
        'RI-6': ['RT', 'RD', 'RC', 'RK', 'R9', 'RN', 'RTA', 'RTB'],
        'DONA': ['DT', 'DD', 'DC', 'DK', 'D9', 'DN', 'DA', 'DB'],
        'Musaking': ['MSKA', 'MSKB']
      };

      // Mapping mã → tên đầy đủ (dùng khi xuất sheet TẤT CẢ)
      const codeToName = {
        RT: 'Sầu riêng Ri 6 Thối',
        RD: 'Sầu riêng Ri 6 Dạt',
        RC: 'Sầu riêng Ri 6 Chiêm',
        RK: 'Sầu riêng Ri 6 Kem',
        R9: 'Sầu riêng Ri 6 Chín cây',
        RN: 'Sầu riêng Ri 6 Nấm',
        RTA: 'Sầu riêng Ri 6 loại 1',
        RTB: 'Sầu riêng Ri 6 loại 2',
        DT: 'Sầu riêng monthong Thối',
        DD: 'Sầu riêng monthong Dạt',
        DC: 'Sầu riêng monthong Chiêm',
        DK: 'Sầu riêng monthong Kem',
        D9: 'Sầu riêng monthong Chín cây',
        DN: 'Sầu riêng monthong Nấm',
        DA: 'Sầu riêng monthong loại A',
        DB: 'Sầu riêng monthong loại B',
        MSKA: 'Sầu riêng Musaking loại A',
        MSKB: 'Sầu riêng Musaking loại B'
      };

      // Mapping mã → mã hàng (NL...) trong mẫu
      const codeToSku = {
        RT: '',
        RD: 'NL1010102.009',
        RC: 'NL1010102.014',
        RK: 'NL1010102.006',
        R9: 'NL1010102.008',
        RN: 'NL1010102.015',
        RTA: 'NL1010102.002',
        RTB: 'NL1010102.003',
        DT: '',
        DD: 'NL1010101.009',
        DC: 'NL1010101.014',
        DK: 'NL1010101.006',
        D9: 'NL1010101.008',
        DN: 'NL1010101.015',
        DA: 'NL1010101.002',
        DB: 'NL1010101.003',
        MSKA: 'NL1010104.002',
        MSKB: 'NL1010104.003'
      };

      const state = {
        weightCols: 11,         // tối đa 11 cột B→L trong mẫu
        rows: [],
        cursorRow: 0,
        cursorCol: 0,
        lastMa: 'DK'
      };

      const els = {
        dateTimeInput: document.getElementById('dateTimeInput'),
        plateNumber: document.getElementById('plateNumber'),
        ttchSlip: document.getElementById('ttchSlip'),
        totalTruckWeight: document.getElementById('totalTruckWeight'),
        lossPercent: document.getElementById('lossPercent'),
        detailRowsBody: document.getElementById('detailRowsBody'),
        summaryContainer: document.getElementById('summaryContainer'),
        tableHeaderRow: document.getElementById('tableHeaderRow'),
        lotContainer: document.getElementById('lotContainer'),
        materialCodeList: document.getElementById('materialCodeList'),
        currentMa: document.getElementById('currentMa'),
        currentKho: document.getElementById('currentKho'),
        bigInput: document.getElementById('bigInput'),
        cursorInfo: document.getElementById('cursorInfo'),
        enterBtn: document.getElementById('enterBtn'),
        nextRowBtn: document.getElementById('nextRowBtn'),
        undoBtn: document.getElementById('undoBtn'),
        saveBtn: document.getElementById('saveBtn'),
        printBtn: document.getElementById('printBtn'),
        excelBtn: document.getElementById('excelBtn'),
        resetBtn: document.getElementById('resetBtn'),
        addRowBtn: document.getElementById('addRowBtn'),
        addColumnBtn: document.getElementById('addColumnBtn'),
        removeColumnBtn: document.getElementById('removeColumnBtn')
      };

      function genId() {
        return `${Date.now()}-${Math.random().toString(16).slice(2, 8)}`;
      }
      function normalizeCode(v) { return String(v || '').trim().toUpperCase(); }
      function sanitize(v) {
        const n = Number(v);
        return Number.isFinite(n) && n >= 0 ? n : 0;
      }
      function fmt(v) {
        return (Number(v) || 0).toLocaleString('vi-VN', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
      }
      function escapeHtml(v) {
        return String(v ?? '')
          .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;').replace(/'/g, '&#039;');
      }
      function getGroup(code) {
        const c = normalizeCode(code);
        for (const [g, codes] of Object.entries(groupConfig)) {
          if (codes.includes(c)) return g;
        }
        return null;
      }
      function rowTotal(row) {
        return (row.weights || []).reduce((s, v) => s + sanitize(v), 0);
      }
      function truckTotal() {
        return state.rows.reduce((s, r) => s + rowTotal(r), 0);
      }
      function lossPercent() {
        const t = truckTotal();
        const ttch = sanitize(els.ttchSlip.value);
        if (!t || !ttch) return 0;
        return (1 - ttch / t) * 100;
      }

      /* ---------- Render ---------- */
      function renderLots() {
        els.lotContainer.innerHTML = Array.from({ length: 8 }, (_, i) => {
          const n = i + 1;
          const def = n === 1 ? 'DM' : n === 2 ? 'DK' : n === 5 ? 'DM' : n === 6 ? 'DK' : '';
          return `
            <div class="rounded-2xl border border-slate-200 bg-slate-50 p-2.5">
              <div class="mb-1.5 text-[10px] font-bold uppercase tracking-wider text-slate-500">Lot QC ${n}</div>
              <div class="grid grid-cols-2 gap-1.5">
                <input id="lot${n}Short" type="text" class="lot-input text-center font-semibold text-xs" value="${def}" placeholder="DM" maxlength="12" />
                <input id="lot${n}Detail" type="text" class="lot-input text-xs" placeholder="D009LD..." />
              </div>
            </div>`;
        }).join('');
      }

      function renderMaterialOptions() {
        els.materialCodeList.innerHTML = materialCatalog.map(c => `<option value="${c}"></option>`).join('');
      }

      function renderHeaders() {
        const kgHeaders = Array.from({ length: state.weightCols }, (_, i) =>
          `<th class="min-w-[72px] bg-slate-100 px-1.5 py-3 text-center font-semibold">
            <span class="inline-flex rounded-md bg-white px-2 py-1 text-[10px] font-bold text-slate-700 shadow-sm">KG ${i + 1}</span>
          </th>`
        ).join('');

        els.tableHeaderRow.innerHTML = `
          <th class="min-w-[50px] rounded-l-xl bg-slate-100 px-2 py-3 text-center font-semibold">#</th>
          <th class="min-w-[110px] bg-slate-100 px-3 py-3 font-semibold">Mã</th>
          ${kgHeaders}
          <th class="min-w-[100px] bg-slate-100 px-3 py-3 font-semibold">Tổng</th>
          <th class="min-w-[150px] bg-slate-100 px-3 py-3 font-semibold">Kho</th>
          <th class="min-w-[90px] rounded-r-xl bg-slate-100 px-3 py-3 text-center font-semibold hide-on-print">Xóa</th>
        `;
      }

      function renderRows() {
        if (!state.rows.length) {
          state.rows.push({
            id: genId(),
            ma: normalizeCode(els.currentMa.value) || 'DK',
            weights: Array.from({ length: state.weightCols }, () => 0),
            kho: 'GIA PHÚC-BI MÃO'
          });
          state.cursorRow = 0;
          state.cursorCol = 0;
        }

        els.detailRowsBody.innerHTML = state.rows.map((row, ri) => {
          const total = rowTotal(row);
          const isActiveRow = ri === state.cursorRow;
          const weightCells = Array.from({ length: state.weightCols }, (_, ci) => {
            const isActive = isActiveRow && ci === state.cursorCol;
            return `
              <td class="align-middle px-1 py-1 ${isActive ? 'active-cell' : ''}">
                <div class="rounded-lg px-2 py-2 text-center text-sm font-medium ${isActive ? 'bg-emerald-100 text-emerald-800 font-bold' : 'bg-white text-slate-700'}">
                  ${fmt(row.weights[ci] || 0)}
                </div>
              </td>`;
          }).join('');

          return `
            <tr class="align-top ${isActiveRow ? 'active-row' : ''}">
              <td class="rounded-l-xl bg-white px-2 py-2 text-center text-xs font-bold text-slate-500 shadow-sm">${ri + 1}</td>
              <td class="bg-white px-2 py-2 shadow-sm">
                <span class="inline-flex rounded-lg bg-slate-100 px-2.5 py-1.5 text-sm font-bold text-slate-800">${escapeHtml(row.ma || '—')}</span>
              </td>
              ${weightCells}
              <td class="bg-white px-2 py-2 text-center font-bold shadow-sm">
                <span class="metric-value rounded-lg bg-emerald-50 px-2.5 py-1.5 text-emerald-700">${fmt(total)}</span>
              </td>
              <td class="bg-white px-2 py-2 shadow-sm">
                <input type="text" class="cell-input text-xs" value="${escapeHtml(row.kho)}"
                  data-row-id="${row.id}" data-field="kho" placeholder="Kho" />
              </td>
              <td class="rounded-r-xl bg-white px-2 py-2 text-center shadow-sm hide-on-print">
                <button type="button" class="rounded-lg border border-red-200 bg-red-50 px-2.5 py-1.5 text-[10px] font-semibold text-red-600 hover:bg-red-100"
                  data-action="delete-row" data-row-id="${row.id}">Xóa</button>
              </td>
            </tr>`;
        }).join('');
      }

      function renderSummary() {
        const totals = {};
        Object.keys(groupConfig).forEach(g => {
          totals[g] = {};
          groupConfig[g].forEach(c => totals[g][c] = 0);
        });
        state.rows.forEach(row => {
          const code = normalizeCode(row.ma);
          const g = getGroup(code);
          if (!g) return;
          totals[g][code] = (totals[g][code] || 0) + rowTotal(row);
        });

        els.summaryContainer.innerHTML = Object.entries(groupConfig).map(([g, codes]) => {
          const rowsHtml = codes.map(c => `
            <div class="flex items-center justify-between gap-2 rounded-xl border border-slate-200 bg-slate-50 px-2.5 py-2">
              <div class="flex items-center gap-2">
                <span class="summary-badge">${c}</span>
              </div>
              <span class="metric-value text-sm font-bold text-slate-800">${fmt(totals[g][c] || 0)}</span>
            </div>`).join('');
          const groupSum = codes.reduce((s, c) => s + (totals[g][c] || 0), 0);
          return `
            <div class="rounded-2xl border border-slate-200 bg-white p-3 shadow-sm">
              <div class="mb-2 flex items-center justify-between">
                <h3 class="text-sm font-bold uppercase tracking-wide text-slate-700">${g}</h3>
                <span class="rounded-full bg-emerald-100 px-2 py-0.5 text-[10px] font-bold text-emerald-700">Tổng</span>
              </div>
              <div class="space-y-1.5">${rowsHtml}</div>
              <div class="mt-2.5 rounded-xl bg-slate-900 px-3 py-2 text-sm font-bold text-white flex justify-between">
                <span>Tổng ${g}</span>
                <span class="metric-value">${fmt(groupSum)}</span>
              </div>
            </div>`;
        }).join('');
      }

      function updateCursorInfo() {
        els.cursorInfo.textContent = `Dòng ${state.cursorRow + 1} • KG ${state.cursorCol + 1}`;
      }

      function updateTotals() {
        const total = truckTotal();
        els.totalTruckWeight.value = fmt(total);
        const ttch = sanitize(els.ttchSlip.value);
        const loss = total && ttch ? lossPercent() : 0;
        els.lossPercent.value = `${loss.toFixed(2)}%`;
        if (ttch > total && total > 0) {
          els.lossPercent.classList.add('text-red-600', 'bg-red-50');
          els.lossPercent.classList.remove('text-amber-700', 'bg-amber-50');
        } else {
          els.lossPercent.classList.remove('text-red-600', 'bg-red-50');
          els.lossPercent.classList.add('text-amber-700', 'bg-amber-50');
        }
        renderSummary();
        updateCursorInfo();
      }

      function renderAll() {
        renderMaterialOptions();
        renderHeaders();
        renderRows();
        updateTotals();
      }

      /* ---------- Logic nhập 1 ô ---------- */
      function ensureRowExists() {
        const khoVal = (els.currentKho?.value || '').trim() || state.rows[state.rows.length - 1]?.kho || 'GIA PHÚC-BI MÃO';
        while (state.rows.length <= state.cursorRow) {
          state.rows.push({
            id: genId(),
            ma: normalizeCode(els.currentMa.value) || state.lastMa || 'DK',
            weights: Array.from({ length: state.weightCols }, () => 0),
            kho: khoVal
          });
        }
        const ma = normalizeCode(els.currentMa.value);
        if (ma) {
          state.rows[state.cursorRow].ma = ma;
          state.lastMa = ma;
        }
        if (els.currentKho?.value !== undefined) {
          state.rows[state.cursorRow].kho = (els.currentKho.value || '').trim() || state.rows[state.cursorRow].kho;
        }
      }

      function doEnter() {
        ensureRowExists();
        const value = sanitize(els.bigInput.value);
        const row = state.rows[state.cursorRow];

        row.weights[state.cursorCol] = value;
        row.ma = normalizeCode(els.currentMa.value) || state.lastMa || 'DK';
        row.kho = (els.currentKho?.value || '').trim() || row.kho || '';
        state.lastMa = row.ma;
        
        if (state.cursorCol < state.weightCols - 1) {
          state.cursorCol += 1;
        } else {
          state.cursorRow += 1;
          state.cursorCol = 0;
          ensureRowExists();
          state.rows[state.cursorRow].ma = normalizeCode(els.currentMa.value) || state.lastMa;
          state.rows[state.cursorRow].kho = (els.currentKho?.value || '').trim() || state.rows[state.cursorRow].kho;
        }

        els.bigInput.value = '';
        els.bigInput.focus();
        renderAll();
        saveLocal();
        showToast(`Đã nhập ${fmt(value)} KG`, 'success');
      }

      function doNextRow() {
        ensureRowExists();
        state.cursorRow += 1;
        state.cursorCol = 0;
        ensureRowExists();
        state.rows[state.cursorRow].ma = normalizeCode(els.currentMa.value) || state.lastMa;
        state.rows[state.cursorRow].kho = (els.currentKho?.value || '').trim() || state.rows[state.cursorRow].kho;
        els.bigInput.value = '';
        els.bigInput.focus();
        renderAll();
        saveLocal();
      }

      function doUndo() {
        if (!state.rows.length) return;
        const row = state.rows[state.cursorRow];
        if (row && row.weights[state.cursorCol] > 0) {
          row.weights[state.cursorCol] = 0;
        } else if (state.cursorCol > 0) {
          state.cursorCol -= 1;
          row.weights[state.cursorCol] = 0;
        } else if (state.cursorRow > 0) {
          state.cursorRow -= 1;
          state.cursorCol = state.weightCols - 1;
          const prev = state.rows[state.cursorRow];
          if (prev) prev.weights[state.cursorCol] = 0;
        }
        renderAll();
        saveLocal();
        els.bigInput.focus();
      }

      /* ---------- Thêm / xóa cột / dòng ---------- */
      function addColumn() {
        // Mẫu Excel chỉ có B→L = 11 cột
        if (state.weightCols >= 11) {
          showToast('Tối đa 11 cột KG (khớp mẫu Excel B→L)', 'warning');
          return;
        }
        state.weightCols += 1;
        state.rows.forEach(r => r.weights.push(0));
        renderAll();
        saveLocal();
      }
      function removeColumn() {
        if (state.weightCols <= 5) {
          showToast('Tối thiểu 5 cột KG', 'warning');
          return;
        }
        state.weightCols -= 1;
        state.rows.forEach(r => r.weights = r.weights.slice(0, state.weightCols));
        if (state.cursorCol >= state.weightCols) state.cursorCol = state.weightCols - 1;
        renderAll();
        saveLocal();
      }
      function addBlankRow() {
        state.rows.push({
          id: genId(),
          ma: normalizeCode(els.currentMa.value) || state.lastMa || '',
          weights: Array.from({ length: state.weightCols }, () => 0),
          kho: ''
        });
        renderAll();
        saveLocal();
      }
      function deleteRow(id) {
        if (state.rows.length <= 1) {
          showToast('Cần ít nhất 1 dòng', 'warning');
          return;
        }
        state.rows = state.rows.filter(r => r.id !== id);
        if (state.cursorRow >= state.rows.length) state.cursorRow = state.rows.length - 1;
        if (state.cursorRow < 0) state.cursorRow = 0;
        renderAll();
        saveLocal();
      }

      /* ---------- Lưu / Khôi phục ---------- */
      const LOT_QC_EXCEL_CELLS = [
        ['C6', 0], ['C7', 1], ['C8', 2], ['C9', 3],
        ['H6', 4], ['H7', 5], ['H8', 6], ['H9', 7]
      ];

      function normalizeLotValue(v) {
        return String(v ?? '').trim().toUpperCase();
      }

      function getLots() {
        return Array.from({ length: 8 }, (_, i) => ({
          short: normalizeLotValue(document.getElementById(`lot${i + 1}Short`)?.value),
          detail: normalizeLotValue(document.getElementById(`lot${i + 1}Detail`)?.value)
        }));
      }

      function saveLocal() {
        const payload = {
          dateTime: els.dateTimeInput.value,
          plateNumber: els.plateNumber.value,
          ttchSlip: els.ttchSlip.value,
          lots: getLots(),
          weightCols: state.weightCols,
          rows: state.rows,
          cursorRow: state.cursorRow,
          cursorCol: state.cursorCol,
          lastMa: state.lastMa,
          currentMa: els.currentMa.value,
          currentKho: els.currentKho ? els.currentKho.value : '',
          savedAt: new Date().toISOString()
        };
        localStorage.setItem(STORAGE_KEY, JSON.stringify(payload));
      }

      function restoreLocal() {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (!raw) {
          state.rows = [{
            id: genId(),
            ma: 'DK',
            weights: Array.from({ length: state.weightCols }, () => 0),
            kho: 'GIA PHÚC-BI MÃO'
          }];
          return;
        }
        try {
          const p = JSON.parse(raw);
          if (p.dateTime) els.dateTimeInput.value = p.dateTime;
          if (p.plateNumber) els.plateNumber.value = p.plateNumber;
          if (p.ttchSlip !== undefined) els.ttchSlip.value = p.ttchSlip;
          if (p.currentMa) els.currentMa.value = p.currentMa;
          if (p.currentKho && els.currentKho) els.currentKho.value = p.currentKho;
          if (p.lastMa) state.lastMa = p.lastMa;
          if (p.weightCols) state.weightCols = Math.min(11, Math.max(5, p.weightCols));
          if (Array.isArray(p.lots)) {
            p.lots.forEach((lot, i) => {
              const s = document.getElementById(`lot${i + 1}Short`);
              const d = document.getElementById(`lot${i + 1}Detail`);
              if (s) s.value = lot.short || '';
              if (d) d.value = lot.detail || '';
            });
          }
          if (Array.isArray(p.rows) && p.rows.length) {
            state.rows = p.rows.map(r => ({
              id: r.id || genId(),
              ma: r.ma || '',
              kho: r.kho || '',
              weights: Array.isArray(r.weights)
                ? r.weights.slice(0, state.weightCols).map(sanitize)
                : Array.from({ length: state.weightCols }, () => 0)
            }));
          }
          state.cursorRow = Math.min(p.cursorRow || 0, Math.max(0, state.rows.length - 1));
          state.cursorCol = Math.min(p.cursorCol || 0, state.weightCols - 1);
        } catch (e) {
          console.warn(e);
        }
      }


      /* =========================================================
         XUẤT EXCEL – COPY ĐÚNG FILE MẪU GỐC (binary) + chỉ ghi ô nhập
         Dùng JSZip sửa XML, không qua ExcelJS → không hỏng file
         ========================================================= */
      // File mẫu gốc nhúng sẵn – copy binary rồi chỉ ghi ô nhập
      const EMBEDDED_TEMPLATE_B64 = "";

      function b64ToArrayBuffer(b64) {
        const binary = atob(b64);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
        return bytes.buffer;
      }

      /**
       * COPY đúng file mẫu gốc → chỉ nhập liệu vào các ô cần thiết.
       * Dùng xlsx-populate để giữ nguyên format, merge, công thức, sheet.
       */
      async function exportExcel() {
        if (!els.plateNumber.value.trim()) {
          showToast('Nhập biển số xe trước khi xuất', 'error');
          els.plateNumber.focus();
          return;
        }

        try {
          if (typeof XlsxPopulate === 'undefined') {
            throw new Error('Thư viện xlsx-populate chưa tải. Kiểm tra mạng / CDN.');
          }

          // 1) Copy file mẫu gốc từ bản nhúng
          const templateBuffer = b64ToArrayBuffer(EMBEDDED_TEMPLATE_B64);
          const workbook = await XlsxPopulate.fromDataAsync(templateBuffer);

          // 2) Lấy sheet CHI TIET
          const ws = workbook.sheet('CHI TIET') || workbook.sheet('CHI TIẾT');
          if (!ws) throw new Error('Không tìm thấy sheet CHI TIET trong file mẫu');

          // 3) Chỉ ghi ô nhập liệu — không đụng công thức

          // Ngày tháng (M4)
          const dt = els.dateTimeInput.value ? new Date(els.dateTimeInput.value) : new Date();
          ws.cell('M4').value(dt);
          ws.cell('M4').style('numberFormat', 'yyyy-mm-dd hh:mm:ss');

          // Biển số xe
          ws.cell('C5').value(els.plateNumber.value.trim());

          // Phiếu TTCH
          ws.cell('M5').value(sanitize(els.ttchSlip.value));

          // Lot QC: ghi cả 8 ô theo cấu trúc mẫu Excel (2 cột x 4 dòng)
          const lots = getLots();
          LOT_QC_EXCEL_CELLS.forEach(([addr, idx]) => {
            const value = lots[idx]?.short || '';
            ws.cell(addr).value(value);
          });

          // Ghi chi tiết lot QC nếu có để tương ứng với từng ô nhập trên giao diện
          // Mẫu Excel không có ô detail nhưng giữ đồng bộ dữ liệu nếu cần xử lý sau

          // Chi tiết cân: dòng 14 trở đi
          // A = mã, B→L = KG, N = kho  |  KHÔNG ghi cột M (công thức SUM)
          state.rows.forEach((row, i) => {
            if (i >= 62) return;
            const r = 14 + i;

            const ma = normalizeCode(row.ma);
            ws.cell(`A${r}`).value(ma || null);

            for (let c = 0; c < 11; c++) {
              const val = sanitize(row.weights[c]);
              // cột B = 2
              ws.cell(r, 2 + c).value(val > 0 ? val : null);
            }

            ws.cell(`N${r}`).value(row.kho || null);
          });

          // 4) Sheet TẤT CẢ + TỔNG giữ nguyên 100% (công thức tự chạy khi mở Excel)

          // 5) Xuất file
          const outBlob = await workbook.outputAsync();
          const url = URL.createObjectURL(outBlob);
          const a = document.createElement('a');
          const plate = els.plateNumber.value.trim().replace(/\s+/g, '-').toUpperCase();
          a.href = url;
          a.download = `phieu-can-tay-${plate}.xlsx`;
          document.body.appendChild(a);
          a.click();
          a.remove();
          setTimeout(() => URL.revokeObjectURL(url), 1000);

          showToast('Đã copy file mẫu và điền dữ liệu', 'success');
        } catch (err) {
          console.error(err);
          showToast('Lỗi xuất Excel: ' + (err.message || err), 'error');
        }
      }

      function showToast(msg, type = 'info') {
        const old = document.getElementById('toast');
        if (old) old.remove();
        const t = document.createElement('div');
        t.id = 'toast';
        const colors = {
          info: 'bg-slate-900 text-white',
          success: 'bg-emerald-600 text-white',
          warning: 'bg-amber-500 text-white',
          error: 'bg-red-600 text-white'
        };
        t.className = `fixed right-4 top-20 z-50 rounded-xl px-4 py-3 text-sm font-medium shadow-lg ${colors[type] || colors.info}`;
        t.textContent = msg;
        document.body.appendChild(t);
        setTimeout(() => t.remove(), 2200);
      }

      function syncDate() {
        const now = new Date();
        const local = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
        if (!els.dateTimeInput.value) els.dateTimeInput.value = local;
      }

      function resetForm() {
        state.weightCols = 11;
        state.rows = [{
          id: genId(),
          ma: 'DK',
          weights: Array.from({ length: 11 }, () => 0),
          kho: 'GIA PHÚC-BI MÃO'
        }];
        state.cursorRow = 0;
        state.cursorCol = 0;
        state.lastMa = 'DK';
        els.currentMa.value = 'DK';
        if (els.currentKho) els.currentKho.value = 'GIA PHÚC-BI MÃO';
        els.plateNumber.value = '';
        els.ttchSlip.value = '';
        els.bigInput.value = '';
        syncDate();
        renderLots();
        renderAll();
        saveLocal();
        showToast('Đã làm mới phiếu', 'success');
      }

      /* ---------- Events ---------- */
      function attachEvents() {
        els.enterBtn.addEventListener('click', doEnter);
        els.nextRowBtn.addEventListener('click', doNextRow);
        els.undoBtn.addEventListener('click', doUndo);

        els.bigInput.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            doEnter();
          }
        });

        els.currentMa.addEventListener('change', () => {
          state.lastMa = normalizeCode(els.currentMa.value) || state.lastMa;
          if (state.rows[state.cursorRow]) {
            state.rows[state.cursorRow].ma = state.lastMa;
            renderAll();
          }
          saveLocal();
        });
        
        if (els.currentKho) {
          els.currentKho.addEventListener('input', () => {
            if (state.rows[state.cursorRow]) {
              state.rows[state.cursorRow].kho = (els.currentKho.value || '').trim();
              renderRows();
            }
            saveLocal();
          });
        }

        els.addColumnBtn.addEventListener('click', addColumn);
        els.removeColumnBtn.addEventListener('click', removeColumn);
        els.addRowBtn.addEventListener('click', addBlankRow);

        els.detailRowsBody.addEventListener('input', (e) => {
          const t = e.target;
          if (t.dataset.field === 'kho' && t.dataset.rowId) {
            const row = state.rows.find(r => r.id === t.dataset.rowId);
            if (row) {
              row.kho = t.value;
              saveLocal();
            }
          }
        });
        els.detailRowsBody.addEventListener('click', (e) => {
          if (e.target.dataset.action === 'delete-row') {
            deleteRow(e.target.dataset.rowId);
          }
        });

        [els.dateTimeInput, els.plateNumber, els.ttchSlip].forEach(el => {
          el.addEventListener('input', () => {
            updateTotals();
            saveLocal();
          });
        });

        for (let i = 1; i <= 8; i++) {
          const s = document.getElementById(`lot${i}Short`);
          const d = document.getElementById(`lot${i}Detail`);
          if (s) s.addEventListener('input', saveLocal);
          if (d) d.addEventListener('input', saveLocal);
        }

        els.saveBtn.addEventListener('click', () => {
          if (!els.plateNumber.value.trim()) {
            showToast('Nhập biển số xe trước khi lưu', 'error');
            els.plateNumber.focus();
            return;
          }
          saveLocal();
          showToast('Đã lưu phiếu (Local)', 'success');
        });

        els.printBtn.addEventListener('click', () => window.print());
        els.excelBtn.addEventListener('click', exportExcel);
        els.resetBtn.addEventListener('click', resetForm);
        window.addEventListener('beforeunload', saveLocal);
      }

      function init() {
        renderLots();
        syncDate();
        restoreLocal();
        renderAll();
        attachEvents();
        els.bigInput.focus();
      }

      init();
